-- A multi-insert COPY into unique indexes that are empty as it starts checks its keys against
-- the keys it entered (exec::dml::FreshUnique) instead of reading the index: the same
-- violations, found at the buffer's flush (1,000 rows or 64 kB of lines) with the line of the
-- row that clashed, the defaults of the buffer's later rows evaluated first; NULLs never
-- clash; a COPY into an index with entries (this transaction's own too) reads it as before.
-- (No ctids after a failed COPY: its buffer's rows after the clashing one are dead tuples in
-- PostgreSQL's heap, which roll's heap model leaves out.)
CREATE TABLE a287_u (id int PRIMARY KEY, a int NOT NULL, b text UNIQUE, s serial) WITH (autovacuum_enabled = off);
CREATE INDEX a287_u_a ON a287_u (a);
SELECT nextval('a287_u_s_seq');
SELECT count(*) FROM a287_u;
SELECT nextval('a287_u_s_seq');
TRUNCATE a287_u;
SELECT ctid, id, a, b, s FROM a287_u WHERE id IN (1, 2, 500, 1500, 2500) ORDER BY id;
SELECT count(*), count(b), sum(a), min(s), max(s) FROM a287_u;
SET enable_seqscan = off;
SELECT count(*) FROM a287_u WHERE id > 0;
SELECT count(*) FROM a287_u WHERE b > '';
RESET enable_seqscan;
SELECT pg_stat_force_next_flush();
SELECT n_tup_ins, n_live_tup, n_dead_tup FROM pg_stat_user_tables WHERE relname = 'a287_u';
TRUNCATE a287_u;
BEGIN;
ROLLBACK;
BEGIN;
SELECT n_tup_ins FROM pg_stat_xact_user_tables WHERE relname = 'a287_u';
COMMIT;
SELECT id, b FROM a287_u ORDER BY id;
DROP TABLE a287_u;
